WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM payments), sessions_payments AS (SELECT id, order_id, amount, paid_at, status, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, order_id, DATE_TRUNC('YEAR', paid_at) AS year_start, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS burst_id_per_refunded, COUNT_IF(status = 'FAILED') AS failed_events, COUNT(*) AS num_rows FROM sessions_payments GROUP BY ROLLUP (DATE_TRUNC('MONTH', paid_at), order_id, DATE_TRUNC('YEAR', paid_at));
